    // MARK: - Find in page (Cmd+F)

    /// JSON-encodes a string for safe embedding in JavaScript source (handles quotes, backslashes, newlines).
    private static func jsStringLiteral(_ s: String) -> String {
        guard let data = try? JSONSerialization.data(withJSONObject: [s]),
              let json = String(data: data, encoding: .utf8) else { return "''" }
        // ["..."] → "..."
        return String(json.dropFirst().dropLast())
    }

    func findInPage(query: String, in tabId: UUID) {
        guard let wv = webViews[tabId], !query.isEmpty else { return }
        lastFindQueryByTab[tabId] = query
        let literal = Self.jsStringLiteral(query)
        wv.evaluateJavaScript("""
            window.getSelection().removeAllRanges();
            window.find(\(literal), false, false, true);
        """, completionHandler: nil)
    }

    func findNext(in tabId: UUID) {
        guard let wv = webViews[tabId], let query = lastFindQueryByTab[tabId] else { return }
        wv.evaluateJavaScript("window.find(\(Self.jsStringLiteral(query)), false, false, true);", completionHandler: nil)
    }

    func findPrevious(in tabId: UUID) {
        guard let wv = webViews[tabId], let query = lastFindQueryByTab[tabId] else { return }
        wv.evaluateJavaScript("window.find(\(Self.jsStringLiteral(query)), false, true, true);", completionHandler: nil)
    }

    func clearFind(in tabId: UUID) {
        guard let wv = webViews[tabId] else { return }
        lastFindQueryByTab.removeValue(forKey: tabId)
        wv.evaluateJavaScript("window.getSelection().removeAllRanges();", completionHandler: nil)
    }

    // MARK: - Zoom (Cmd+ / Cmd- / Cmd0)

    func zoomIn(_ tabId: UUID?) {
        guard let id = tabId ?? activeTab else { return }
        let current = zoomByTab[id] ?? 1.0
        setZoom(min(current + zoomStep, zoomMax), for: id)
    }

    func zoomOut(_ tabId: UUID?) {
        guard let id = tabId ?? activeTab else { return }
        let current = zoomByTab[id] ?? 1.0
        setZoom(max(current - zoomStep, zoomMin), for: id)
    }

    /// The tab's zoom (1.0 = 100%).
    func zoomLevel(_ tabId: UUID?) -> CGFloat {
        guard let id = tabId ?? activeTab else { return 1 }
        return zoomByTab[id] ?? 1.0
    }

    func zoomReset(_ tabId: UUID?) {
        guard let id = tabId ?? activeTab else { return }
        setZoom(1.0, for: id)
    }

    private func setZoom(_ zoom: CGFloat, for tabId: UUID) {
        zoomByTab[tabId] = zoom
        applyZoom(to: tabId)
    }

    private func applyZoom(to tabId: UUID) {
        guard let wv = webViews[tabId] else { return }
        let zoom = zoomByTab[tabId] ?? 1.0
        wv.pageZoom = Double(zoom)
    }

    /// Fetches the favicon URL from the page's <link rel="icon"> tag
    private func fetchFavicon(for tabId: UUID, webView: WKWebView) {
        let script = """
        (function() {
            var links = document.querySelectorAll('link[rel*="icon"]');
            for (var i = 0; i < links.length; i++) {
                var href = links[i].getAttribute('href');
                // Resolve against the document (relative, protocol-relative); data: URIs pass through.
                if (href) { try { return new URL(href, document.baseURI).href; } catch (e) {} }
            }
            return '';
        })();
        """
        
        webView.evaluateJavaScript(script) { [weak self] result, error in
            guard let self = self else { return }
            DispatchQueue.main.async {
                if let urlString = result as? String, !urlString.isEmpty, let url = URL(string: urlString) {
                    self.faviconURLByTab[tabId] = url
                    self.fetchPrimaryTintFromFavicon(for: tabId, faviconURL: url)
                } else if let pageURL = webView.url, let host = pageURL.host {
                    // Fallback to /favicon.ico
                    let url = URL(string: "https://\(host)/favicon.ico")
                    self.faviconURLByTab[tabId] = url
                    if let url { self.fetchPrimaryTintFromFavicon(for: tabId, faviconURL: url) }
                } else {
                    self.faviconURLByTab[tabId] = nil
                }
            }
        }
    }

    private func fetchPrimaryTintFromFavicon(for tabId: UUID, faviconURL: URL) {
        if let data = FaviconCache.decodeDataURI(faviconURL) {
            if let image = NSImage(data: data), let color = Self.dominantColor(from: image) { updatePrimaryTint(color, for: tabId) }
            return
        }
        var request = URLRequest(url: faviconURL)
        request.cachePolicy = .returnCacheDataElseLoad
        URLSession.shared.dataTask(with: request) { [weak self] data, _, _ in
            guard let self else { return }
            guard let data, let image = NSImage(data: data), let color = Self.dominantColor(from: image) else { return }
            DispatchQueue.main.async {
                self.updatePrimaryTint(color, for: tabId)
            }
        }.resume()
    }
    
    /// Extracts the page title from the active tab.
    func evaluatePageTitle(completion: @escaping (String?) -> Void) {
        guard let tabId = activeTab, let wv = webViews[tabId] else {
            DispatchQueue.main.async { completion(nil) }
            return
        }
        wv.evaluateJavaScript("document.title") { result, error in
            DispatchQueue.main.async {
                if error != nil {
                    completion(nil)
                    return
                }
                if let title = result as? String, !title.isEmpty {
                    completion(title)
                } else {
                    completion(nil)
                }
            }
        }
    }

    /// The active tab's web view, for the computer-use agent.
    var activeWebView: WKWebView? {
        activeTab.flatMap { webViews[$0] }
    }

    /// Extracts visible text from the page, bounded to maxChars (default 4000, hard max 12000 per AGENTS.md).
    func evaluateVisibleText(maxChars: Int = 4000, completion: @escaping (String?) -> Void) {
        guard let tabId = activeTab, webViews[tabId] != nil else {
            DispatchQueue.main.async { completion(nil) }
            return
        }
        evaluateVisibleText(for: tabId, maxChars: maxChars, completion: completion)
    }
    
    /// Extracts visible text from a specific tab, bounded to maxChars (default 4000, hard max 12000 per AGENTS.md).
    func evaluateVisibleText(for tabId: UUID, maxChars: Int = 4000, completion: @escaping (String?) -> Void) {
        guard let wv = webViews[tabId] else {
            DispatchQueue.main.async { completion(nil) }
            return
        }
        let limit = min(maxChars, 12000)
        let js = "document.body.innerText.substring(0, \(limit))"
        wv.evaluateJavaScript(js) { result, error in
            DispatchQueue.main.async {
                if error != nil {
                    completion(nil)
                    return
                }
                if let text = result as? String, !text.isEmpty {
                    completion(text)
                } else {
                    completion(nil)
                }
            }
        }
    }
    
    /// Evaluates page title for a specific tab.
    func evaluatePageTitle(for tabId: UUID, completion: @escaping (String?) -> Void) {
        guard let wv = webViews[tabId] else {
            DispatchQueue.main.async { completion(nil) }
            return
        }
        wv.evaluateJavaScript("document.title") { result, error in
            DispatchQueue.main.async {
                if error != nil {
                    completion(nil)
                    return
                }
                if let title = result as? String, !title.isEmpty {
                    completion(title)
                } else {
                    completion(nil)
                }
            }
        }
    }

    /// Removes a tab's WebView when the tab is closed.
    /// - Parameter keepMetadata: true when hibernating, so the tab keeps its
    ///   favicon, tint, theme and zoom while unloaded.
    func removeWebView(for tabId: UUID, keepMetadata: Bool = false) {
        observations.removeValue(forKey: tabId)
        lastFindQueryByTab.removeValue(forKey: tabId)
        // Stop any in-flight load and detach delegates so callbacks can't fire during teardown.
        if let wv = webViews[tabId] {
            wv.stopLoading()
            wv.navigationDelegate = nil
            wv.uiDelegate = nil
        }
        webViews.removeValue(forKey: tabId)
        popupTabIds.remove(tabId)
        loadingProgressByTab.removeValue(forKey: tabId)
        pageErrorByTab.removeValue(forKey: tabId)
        audibleFramesByTab.removeValue(forKey: tabId)
        audibleTabs.remove(tabId)
        mutedTabs.remove(tabId)
        if !keepMetadata {
            faviconURLByTab.removeValue(forKey: tabId)
            primaryTintByTab.removeValue(forKey: tabId)
            pageThemeByTab.removeValue(forKey: tabId)
            zoomByTab.removeValue(forKey: tabId)
            canGoBackByTab.removeValue(forKey: tabId)
            canGoForwardByTab.removeValue(forKey: tabId)
        }
        if activeTab == tabId {
            activeTab = nil
            currentURL = nil
            pageThemeForActiveTab = nil
            canGoBackForActiveTab = false
            canGoForwardForActiveTab = false
        } else {
            updatePageThemeForActiveTab()
            updateBackForwardForActiveTab()
        }
    }

    func removeAllWebViews() {
        for tabId in Array(webViews.keys) {
            removeWebView(for: tabId)
        }
    }

    // MARK: - WKNavigationDelegate

    func webView(_ webView: WKWebView, decidePolicyFor navigationAction: WKNavigationAction, preferences: WKWebpagePreferences, decisionHandler: @escaping (WKNavigationActionPolicy, WKWebpagePreferences) -> Void) {
        if navigationAction.shouldPerformDownload {
            downloadLog.info("Navigation marked as download: \(navigationAction.request.url?.absoluteString ?? "nil", privacy: .public)")
            decisionHandler(.download, preferences)
            return
        }
        // ⌘-click / middle-click a link (or a target=_blank link): open it in a new tab
        // next to this one, in the background unless Shift is held (Chrome).
        if let url = navigationAction.request.url,
           let foreground = Self.newTabDisposition(type: navigationAction.navigationType,
                                                  modifiers: navigationAction.modifierFlags,
                                                  button: navigationAction.buttonNumber),
           ["http", "https", "file"].contains(url.scheme?.lowercased() ?? ""),
           let opener = tabId(for: webView) {
            openInNewTab(url, nextTo: opener, foreground: foreground)
            decisionHandler(.cancel, preferences)
            return
        }
        // Switch UA on the fly so redirects (e.g. Gmail → accounts.google.com)
        // pick up the correct UA for the target host.
        if let targetURL = navigationAction.request.url {
            webView.customUserAgent = Self.userAgent(for: targetURL)
        }
        preferences.allowsContentJavaScript = true
        decisionHandler(.allow, preferences)
    }

    func webView(_ webView: WKWebView, didFailProvisionalNavigation navigation: WKNavigation!, withError error: any Error) {
        let url = webView.url?.absoluteString ?? "(unknown url)"
        print("WKWebView didFailProvisionalNavigation:", url, error.localizedDescription)
        guard let tabId = tabId(for: webView), let pageError = PageError.classify(error, url: webView.url) else { return }
        pageErrorByTab[tabId] = pageError
        // The address bar shows the page that failed, not the one still underneath.
        if tabId == activeTab, let failed = pageError.url { currentURL = failed }
    }

    func webView(_ webView: WKWebView, didFail navigation: WKNavigation!, withError error: any Error) {
        let url = webView.url?.absoluteString ?? "(unknown url)"
        print("WKWebView didFail:", url, error.localizedDescription)
    }

    func webViewWebContentProcessDidTerminate(_ webView: WKWebView) {
        let url = webView.url?.absoluteString ?? "(unknown url)"
        print("WKWebView process terminated:", url)
        guard let tabId = tabId(for: webView) else { return }
        pageErrorByTab[tabId] = PageError(kind: .crashed, url: webView.url, code: nil)
        loadingProgressByTab.removeValue(forKey: tabId)
        setAudible(false, frame: nil, in: tabId)
    }

    /// The error page's Reload: retries the page that failed (a crashed tab reloads in a new process).
    func reloadAfterError(in tabId: UUID) {
        guard let error = pageErrorByTab.removeValue(forKey: tabId) else { return reload(in: tabId) }
        if error.kind != .crashed, let url = error.url, url != webViews[tabId]?.url {
            load(url: url, in: tabId)
        } else {
            reload(in: tabId)
        }
    }

    // MARK: - HTTP authentication

    func webView(_ webView: WKWebView, didReceive challenge: URLAuthenticationChallenge,
                 completionHandler: @escaping (URLSession.AuthChallengeDisposition, URLCredential?) -> Void) {
        let method = challenge.protectionSpace.authenticationMethod
        // Server trust and client certificates: WebKit's default handling (never bypass TLS).
        guard method == NSURLAuthenticationMethodHTTPBasic || method == NSURLAuthenticationMethodHTTPDigest
                || method == NSURLAuthenticationMethodDefault else {
            return completionHandler(.performDefaultHandling, nil)
        }
        // Give up after a few wrong passwords instead of re-prompting forever.
        guard challenge.previousFailureCount < 3 else { return completionHandler(.cancelAuthenticationChallenge, nil) }
        AuthChallengeSheet.present(for: challenge.protectionSpace, previous: challenge.proposedCredential,
                                   in: webView.window ?? NSApp.keyWindow ?? NSApp.mainWindow) { credential in
            if let credential {
                completionHandler(.useCredential, credential)
            } else {
                completionHandler(.cancelAuthenticationChallenge, nil)
            }
        }
    }

    /// MIME types we display in the WebView (PDF + web/image types). Word docs download to avoid gibberish.
    private static let displayableMIMETypes: Set<String> = [
        "text/html", "text/plain", "text/css", "text/javascript", "application/javascript",
        "application/json", "application/xml", "image/svg+xml",
        "image/jpeg", "image/png", "image/gif", "image/webp", "image/bmp", "image/x-icon",
        "application/pdf"
    ]

    func webView(_ webView: WKWebView, decidePolicyFor navigationResponse: WKNavigationResponse, decisionHandler: @escaping (WKNavigationResponsePolicy) -> Void) {
        // 0) Local file:// URLs: always display in browser (don't treat as download)
        if navigationResponse.response.url?.scheme?.lowercased() == "file" {
            decisionHandler(.allow)
            return
        }
        // 1) HTTP redirect (3xx): always allow so redirect chains (e.g. library resolvers, SSO) complete
        if let http = navigationResponse.response as? HTTPURLResponse,
           (300...399).contains(http.statusCode) {
            decisionHandler(.allow)
            return
        }
        // 2) Server says "save as file" → always download
        if let http = navigationResponse.response as? HTTPURLResponse,
           let disposition = http.value(forHTTPHeaderField: "Content-Disposition"),
           disposition.lowercased().contains("attachment") {
            decisionHandler(.download)
            return
        }
        // 3) Main-frame navigation to remote image/* (HEIC, PNG, JPEG, etc.): download to Downloads
        //    (subresources like <img> on a page stay allowed so images display)
        let scheme = navigationResponse.response.url?.scheme?.lowercased()
        let mime = (navigationResponse.response.mimeType ?? "").lowercased()
        let requestURL = navigationResponse.response.url
        if navigationResponse.isForMainFrame,
           (scheme == "http" || scheme == "https"),
           mime.hasPrefix("image/") {
            decisionHandler(.download)
            return
        }
        // 4) Display web/document content; always allow resolver/document URLs (e.g. Primo, Alma) even with wrong MIME
        if navigationResponse.isForMainFrame, (scheme == "http" || scheme == "https"),
           Self.looksLikeDocumentURL(requestURL) {
            decisionHandler(.allow)
            return
        }
        // 5) Standard displayable types
        let isDisplayable: Bool = {
            if mime.isEmpty { return true }
            if Self.displayableMIMETypes.contains(mime) { return true }
            if mime.hasPrefix("image/") { return true }
            if mime.hasPrefix("text/") { return true }
            if mime == "application/xhtml+xml" { return true }
            return false
        }()
        if isDisplayable && navigationResponse.canShowMIMEType {
            decisionHandler(.allow)
        } else {
            decisionHandler(.download)
        }
    }

    /// URLs that are typically HTML documents (resolvers, .do, /view/, etc.) so we allow display even when MIME is wrong.
    private static func looksLikeDocumentURL(_ url: URL?) -> Bool {
        guard let url = url else { return false }
        let s = url.absoluteString.lowercased()
        let path = url.path.lowercased()
        return path.contains("/view/") || path.contains("/action/") || path.hasSuffix(".do") || s.contains("uresolver") || s.contains("resolver")
    }

    func webView(_ webView: WKWebView, navigationAction: WKNavigationAction, didBecome download: WKDownload) {
        download.delegate = self
        if navigationAction.targetFrame?.isMainFrame ?? true { mainFrameNavigationBecameDownload(in: webView) }
    }

    func webView(_ webView: WKWebView, navigationResponse: WKNavigationResponse, didBecome download: WKDownload) {
        download.delegate = self
        if navigationResponse.isForMainFrame { mainFrameNavigationBecameDownload(in: webView) }
    }

    private func mainFrameNavigationBecameDownload(in webView: WKWebView) {
        guard let tabId = webViews.first(where: { $0.value === webView })?.key else { return }
        let committed = webView.backForwardList.currentItem?.url
        let isPopup = popupTabIds.contains(tabId)
        DispatchQueue.main.async { [weak self] in
            self?.onTabNavigationBecameDownload?(tabId, committed, isPopup)
        }
    }

    func webView(_ webView: WKWebView, didCommit navigation: WKNavigation!) {
        guard let tabId = tabId(for: webView) else { return }
        if pageErrorByTab[tabId] != nil { pageErrorByTab.removeValue(forKey: tabId) }
        // The old document's media is gone; frames of the new one report again.
        setAudible(false, frame: nil, in: tabId)
        if passwordFillOffer?.tabId == tabId { passwordFillOffer = nil }
    }

    func webView(_ webView: WKWebView, didFinish navigation: WKNavigation!) {
        guard let tabId = webViews.first(where: { $0.value === webView })?.key else { return }
        if let url = webView.url {
            let title = webView.title?.trimmingCharacters(in: .whitespacesAndNewlines)
            onNavigationFinished?(tabId, url, (title?.isEmpty == false ? title! : (url.host ?? url.absoluteString)))
        }
        if tabId == activeTab {
            DispatchQueue.main.async { [weak self] in
                self?.currentURL = webView.url
            }
        }
        // Update back/forward state so toolbar buttons enable/disable correctly.
        canGoBackByTab[tabId] = webView.canGoBack
        canGoForwardByTab[tabId] = webView.canGoForward
        updateBackForwardForActiveTab()
        // Re-apply per-tab zoom after load
        applyZoom(to: tabId)
        // Fallback: sample theme again at load end (documentEnd script may have already run).
        let script = """
        (function(){
            var el = document.body || document.documentElement;
            if (!el) return null;
            var bg = window.getComputedStyle(el).backgroundColor;
            if (!bg || bg === 'transparent' || bg === 'rgba(0, 0, 0, 0)') { el = document.documentElement; bg = el ? window.getComputedStyle(el).backgroundColor : null; }
            if (!bg || bg === 'transparent') return null;
            var m = bg.match(/rgb\\(\\s*(\\d+)\\s*,\\s*(\\d+)\\s*,\\s*(\\d+)\\s*\\)/);
            if (m) return m[1] + ',' + m[2] + ',' + m[3];
            var m2 = bg.match(/rgba\\(\\s*(\\d+)\\s*,\\s*(\\d+)\\s*,\\s*(\\d+)/);
            if (m2) return m2[1] + ',' + m2[2] + ',' + m2[3];
            if (bg.indexOf('#') === 0 && bg.length >= 7) { var r=parseInt(bg.slice(1,3),16),g=parseInt(bg.slice(3,5),16),b=parseInt(bg.slice(5,7),16); return r+','+g+','+b; }
            if (bg.length === 4) { var r=parseInt(bg[1]+bg[1],16),g=parseInt(bg[2]+bg[2],16),b=parseInt(bg[3]+bg[3],16); return r+','+g+','+b; }
            return null;
        })();
        """
        webView.evaluateJavaScript(script) { [weak self] result, _ in
            guard let self = self else { return }
            let (color, isDark) = Self.parsePageTheme(result)
            DispatchQueue.main.async {
                if let color = color {
                    self.pageThemeByTab[tabId] = (color, isDark)
                    // Fallback tint when favicon tint isn't available yet.
                    if self.primaryTintByTab[tabId] == nil {
                        self.updatePrimaryTint(color, for: tabId)
                    }
                } else {
                    self.pageThemeByTab.removeValue(forKey: tabId)
                }
                self.updatePageThemeForActiveTab()
            }
        }
    }

    fileprivate func updatePageThemeForActiveTab() {
        guard let id = activeTab, let theme = pageThemeByTab[id] else {
            pageThemeForActiveTab = nil
            return
        }
        pageThemeForActiveTab = (Color(nsColor: theme.color), theme.isDark)
    }

    private func updateBackForwardForActiveTab() {
        guard let id = activeTab else {
            canGoBackForActiveTab = false
            canGoForwardForActiveTab = false
            return
        }
        canGoBackForActiveTab = canGoBackByTab[id] ?? webViews[id]?.canGoBack ?? false
        canGoForwardForActiveTab = canGoForwardByTab[id] ?? webViews[id]?.canGoForward ?? false
    }

    /// Parse JS result (e.g. "255,255,255" or null) into NSColor and luminance-based isDark.
    fileprivate static func parsePageTheme(_ result: Any?) -> (NSColor?, Bool) {
        guard let str = result as? String, !str.isEmpty else { return (nil, false) }
        let parts = str.split(separator: ",").compactMap { Int($0.trimmingCharacters(in: .whitespaces)) }
        guard parts.count >= 3 else { return (nil, false) }
        let r = min(255, max(0, parts[0])), g = min(255, max(0, parts[1])), b = min(255, max(0, parts[2]))
        let ns = NSColor(red: CGFloat(r)/255, green: CGFloat(g)/255, blue: CGFloat(b)/255, alpha: 1)
        // Relative luminance (WCAG). If luminance is high, background is "light" so we should use dark text.
        let luminance = relativeLuminance(ns)
        return (ns, luminance <= 0.5)
    }

    /// Downloads a URL picked from the page's context menu.
    private func startDownload(of url: URL, from webView: WKWebView) {
        if url.scheme == "data" {
            // Inline images (e.g. Google Images thumbnails) are already in the URL.
            guard let data = try? Data(contentsOf: url) else { return }
            DownloadManager.shared.save(data, mimeType: Self.dataURLMIMEType(url), sourceURL: webView.url ?? url)
            return
        }
        var request = URLRequest(url: url)
        if let page = webView.url { request.setValue(page.absoluteString, forHTTPHeaderField: "Referer") }
        webView.startDownload(using: request) { [weak self] download in
            download.delegate = self
        }
    }

    private static func dataURLMIMEType(_ url: URL) -> String? {
        let header = url.absoluteString.dropFirst("data:".count).prefix { $0 != "," }
        return header.split(separator: ";").first.map(String.init)
    }

    // MARK: - WKDownloadDelegate (saves to ~/Downloads, notifies DownloadManager)

    func download(_ download: WKDownload, decideDestinationUsing response: URLResponse, suggestedFilename: String, completionHandler: @escaping (URL?) -> Void) {
        let downloadsDir = FileManager.default.urls(for: .downloadsDirectory, in: .userDomainMask).first!
        var dest = downloadsDir.appendingPathComponent(suggestedFilename)
        let pathExt = dest.pathExtension
        let base = dest.deletingPathExtension().lastPathComponent
        var counter = 1
        while FileManager.default.fileExists(atPath: dest.path) {
            let name = pathExt.isEmpty ? "\(base) (\(counter))" : "\(base) (\(counter)).\(pathExt)"
            dest = downloadsDir.appendingPathComponent(name)
            counter += 1
        }
        let requestURL = response.url ?? download.originalRequest?.url ?? dest
        downloadItemByID[ObjectIdentifier(download)] = DownloadManager.shared.begin(
            download, url: requestURL, fileURL: dest, suggestedFilename: suggestedFilename)
        downloadLog.info("Saving download to \(dest.path, privacy: .public)")
        completionHandler(dest)
    }

    func downloadDidFinish(_ download: WKDownload) {
        guard let id = downloadItemByID.removeValue(forKey: ObjectIdentifier(download)) else { return }
        DownloadManager.shared.finish(id)
    }

    func download(_ download: WKDownload, didFailWithError error: any Error, resumeData: Data?) {
        downloadLog.error("Download failed: \(download.originalRequest?.url?.absoluteString ?? "(unknown)", privacy: .public) \(String(describing: error), privacy: .public)")
        guard let id = downloadItemByID.removeValue(forKey: ObjectIdentifier(download)) else { return }
        DownloadManager.shared.fail(id, error: error)
    }

    // MARK: - WKUIDelegate

    /// Handle `target="_blank"` / `window.open()` by creating a new tab *and returning a real WKWebView*.
    ///
    /// Important: returning `nil` breaks flows that depend on the opener relationship and/or the browser
    /// performing the navigation (proper `Referer`, cookies, redirects, and window scripting). Many library
    /// resolvers (Primo/Alma) rely on this behavior.
    func webView(_ webView: WKWebView, createWebViewWith configuration: WKWebViewConfiguration, for navigationAction: WKNavigationAction, windowFeatures: WKWindowFeatures) -> WKWebView? {
        // If targetFrame exists, the navigation is for an existing frame (e.g., iframe) - let it proceed.
        guard navigationAction.targetFrame == nil else { return nil }

        let requestURL = navigationAction.request.url
        
        // Allow about:blank - Google Docs and other apps use window.open() with no URL initially,
        // then navigate the popup via JavaScript. Blocking about:blank breaks these flows.
        let isAboutBlank = requestURL?.absoluteString == "about:blank" || requestURL == nil
        
        if !isAboutBlank {
            guard let url = requestURL,
                  let scheme = url.scheme?.lowercased(),
                  (scheme == "http" || scheme == "https" || scheme == "file") else {
                print("WebViewWrapper: Blocked navigation to invalid URL: \(requestURL?.absoluteString ?? "nil")")
                return nil
            }
        }

        // If tabManager is unavailable, fall back to loading in current tab instead of blocking entirely.
        guard let tabManager = tabManager else {
            if let url = requestURL {
                print("WebViewWrapper: tabManager is nil, loading \(url.absoluteString) in current tab")
                webView.load(URLRequest(url: url))
            }
            return nil
        }

        print("WebViewWrapper: Creating new tab for popup: \(requestURL?.absoluteString ?? "about:blank")")

        // Create a new tab and *return* its webview so WebKit performs the navigation with correct headers.
        // For about:blank popups, pass nil so TabManager creates a blank tab that will be navigated later.
        let id = tabManager.newTab(url: requestURL)
        // IMPORTANT: the returned WKWebView must be created with the provided `configuration`,
        // otherwise WebKit throws: "Returned WKWebView was not created with the given configuration."
        // The supplied popup configuration inherits the opener's profile store.
        Self.applyDeveloperTools(to: configuration)
        configuration.defaultWebpagePreferences.allowsContentJavaScript = true
        let wv = LunaWebView(frame: .zero, configuration: configuration)
        wv.customUserAgent = Self.userAgent(for: requestURL)
        register(webView: wv, for: id)
        popupTabIds.insert(id)

        setActiveTab(id)
        // Do NOT call `load()` here — WebKit will load `navigationAction.request` into the returned webview.
        return wv
    }

    func webView(_ webView: WKWebView, runOpenPanelWith parameters: WKOpenPanelParameters, initiatedByFrame frame: WKFrameInfo, completionHandler: @escaping ([URL]?) -> Void) {
        let panel = NSOpenPanel()
        panel.allowsMultipleSelection = parameters.allowsMultipleSelection
        panel.canChooseDirectories = parameters.allowsDirectories
        panel.canChooseFiles = true
        panel.begin { response in
            if response == .OK {
                completionHandler(panel.urls)
            } else {
                completionHandler(nil)
            }
        }
    }

    // MARK: - JavaScript dialogs

    func webView(_ webView: WKWebView, runJavaScriptAlertPanelWithMessage message: String, initiatedByFrame frame: WKFrameInfo, completionHandler: @escaping () -> Void) {
        let alert = NSAlert()
        alert.messageText = message
        alert.alertStyle = .informational
        alert.addButton(withTitle: "OK")
        if let window = webView.window ?? NSApp.keyWindow ?? NSApp.mainWindow {
            alert.beginSheetModal(for: window) { _ in completionHandler() }
        } else {
            alert.runModal()
            completionHandler()
        }
    }

    func webView(_ webView: WKWebView, runJavaScriptConfirmPanelWithMessage message: String, initiatedByFrame frame: WKFrameInfo, completionHandler: @escaping (Bool) -> Void) {
        let alert = NSAlert()
        alert.messageText = message
        alert.alertStyle = .informational
        alert.addButton(withTitle: "OK")
        alert.addButton(withTitle: "Cancel")
        if let window = webView.window ?? NSApp.keyWindow ?? NSApp.mainWindow {
            alert.beginSheetModal(for: window) { response in completionHandler(response == .alertFirstButtonReturn) }
        } else {
            completionHandler(alert.runModal() == .alertFirstButtonReturn)
        }
    }

    func webView(_ webView: WKWebView, runJavaScriptTextInputPanelWithPrompt prompt: String, defaultText: String?, initiatedByFrame frame: WKFrameInfo, completionHandler: @escaping (String?) -> Void) {
        let alert = NSAlert()
        alert.messageText = prompt
        alert.alertStyle = .informational
        alert.addButton(withTitle: "OK")
        alert.addButton(withTitle: "Cancel")

        let textField = NSTextField(frame: NSRect(x: 0, y: 0, width: 300, height: 24))
        textField.stringValue = defaultText ?? ""
        alert.accessoryView = textField

        if let window = webView.window ?? NSApp.keyWindow ?? NSApp.mainWindow {
            alert.beginSheetModal(for: window) { response in
                completionHandler(response == .alertFirstButtonReturn ? textField.stringValue : nil)
            }
        } else {
            completionHandler(alert.runModal() == .alertFirstButtonReturn ? textField.stringValue : nil)
        }
    }

    func webViewDidClose(_ webView: WKWebView) {
        // A popup window closed itself via window.close() - close the corresponding tab.
        guard let tabId = webViews.first(where: { $0.value === webView })?.key else { return }
        print("WebViewWrapper: Popup closed via window.close(), removing tab \(tabId)")
        tabManager?.closeTab(tabId)
        removeWebView(for: tabId)
    }
}

// MARK: - Media message handler (isolated content world, all frames)

private final class MediaMessageHandler: NSObject, WKScriptMessageHandler {
    weak var wrapper: WebViewWrapper?

    func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
        let body = message.body
        let webView = message.webView
        DispatchQueue.main.async { [weak self] in self?.wrapper?.handleMediaMessage(body, from: webView) }
    }
}

// MARK: - Password message handler (isolated content world)

private final class PasswordMessageHandler: NSObject, WKScriptMessageHandler {
    weak var wrapper: WebViewWrapper?

    func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
        guard message.frameInfo.isMainFrame else { return }
        let body = message.body
        let webView = message.webView
        DispatchQueue.main.async { [weak self] in self?.wrapper?.handlePasswordMessage(body, from: webView) }
    }
}

// MARK: - Link preview message handler (isolated content world)

private final class LinkPreviewMessageHandler: NSObject, WKScriptMessageHandler {
    weak var wrapper: WebViewWrapper?

    func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
        let body = message.body
        let webView = message.webView
        DispatchQueue.main.async { [weak self] in self?.wrapper?.handleLinkPreview(body, from: webView) }
    }
}

// MARK: - Theme message handler (receives theme from documentEnd script for instant chrome color)

private final class ThemeMessageHandler: NSObject, WKScriptMessageHandler {
    weak var wrapper: WebViewWrapper?

    func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
        guard let wrapper = wrapper else { return }
        guard let wv = message.webView, let tabId = wrapper.tabId(for: wv) else { return }
        let (color, isDark) = WebViewWrapper.parsePageTheme(message.body)
        DispatchQueue.main.async {
            if let color = color {
                wrapper.pageThemeByTab[tabId] = (color, isDark)
            } else {
                wrapper.pageThemeByTab.removeValue(forKey: tabId)
            }
            wrapper.updatePageThemeForActiveTab()
        }
    }
}

// MARK: - Google “suspicious request” handler (shows in-app explanation so users know it’s Google’s decision, not Luma)

private final class GoogleSuspiciousErrorHandler: NSObject, WKScriptMessageHandler {
    weak var wrapper: WebViewWrapper?

    func userContentController(_ userContentController: WKUserContentController, didReceive message: WKScriptMessage) {
        DispatchQueue.main.async { [weak self] in
            self?.wrapper?.googleSuspiciousErrorDetected = true
        }
    }
}
